#define PI 3.141592
#define tt iTime
#define S(a, b, x) smoothstep(a, b, x)
#define rot(x) mat2(cos(x), -sin(x), sin(x), cos(x))

vec3 pal(float x) {
    return .5+.5*cos(2.*PI*x+vec3(0, 8, 10));

}

float circle(vec2 p, float r) {
    return length(p) - r;
}

float box(vec2 p, vec2 s) {
    p = abs(p);
    return max(p.x - s.x, p.y - s.y);
}

vec2 toPolar(vec2 p) {
    float a = atan(p.y, p.x);
    float r = length(p);

    return vec2(r, a);
}

vec2 fromPolar(vec2 p) {

    return p.x*vec2(cos(p.y), sin(p.y));
}
float rug(vec2 p) {


    p = fract(p*2.)-.5;


  //  fe
      p = abs(p)-.1;
    for(float i=.0; i< 5.; i++ ) {
       p.x = abs(p.x) - .2;
       p.x += sin(p.y*.2+i)*.3;
       p.xy *= rot(PI/9.+i+.05*tt); 
    }
        p = toPolar(p);
    float N = 2.;
    p.y = fract(p.y*N/PI*2.)-.5; 
    p.x = abs(p.x)+ .3;
    p = fromPolar(p);



    vec2 bp = p;

    float d = 1e0;

    p.x -= .2;
    d = circle(p, .4);
    d = abs(d) - .02;

    p = bp;

    p.x += .2;
    float d2 = circle(p, .4);
    d2 = abs(d2) - .04;

    d = min(d, d2);

    p = bp;
    p = abs(p);
    p.x -= .49;
    p.xy *= rot(.25*PI);

    d2 = box(p, vec2(.19));
    d2 = abs(d2) - .02;

    d = min(d, d2);

    d = abs(d) -.003;

    return d;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
     uv += sin(uv.yx*4.+tt)*0.03;
    vec2 uvb = uv;
    uv *= 1.3;

    float d = rug(fract(uv*2.));
    float s1 = (1.-S(0., .4, d));

    vec3 col =  pal(-d*20. + (abs(uv.x)+abs(uv.y)))*s1;

    float d2 = (rug(uv));
    float s2 = (1.-S(0., .01, d2));
    col = mix(pal(-d2*20.-.8+abs(uv.x)+abs(uv.y))*s2, col, s1);


    col = mix(mix(vec3(0.718,0.145,0.043), vec3(0.957,0.718,0.204)*.2, abs(uv.x)), col, dot(col, vec3(1)));

    col *= S(0.0, 0.01, d2*2.);


    float rimd = abs(box(uvb, vec2(.62, .4)*.8))- 0.03; 
    float rim = S(0., .005, rimd);
    col *= rim;

    vec3 rimCol = pal(-rimd*10.-.8+abs(uv.x)+abs(uv.y));
    float circles = abs(circle(fract(uv*18.)-.5, .2)) -.1;

    col += (1.-rim)*(1.-S(0., .1, abs(circles)-.02)*S(0., 0.01, abs(rimd)))*rimCol;



    col *= 1.-S(0., .02, box(uvb, vec2(.6, .4)));
    float edge = (1.-S(0., .01, abs(box(uvb, vec2(.6, .4))-.01)));
    col = mix(col, rimCol, edge);
    col *= 1.-.9*texture(iChannel0, uvb*3.).r; 
    fragColor = vec4(vec3(col), 1);
}
